import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ConfigLoaderTest {
    private static final String REQUIRED = """
            upstream.url=https://uplink.example.com/v1/events
            api.token=s3cret
            """;

    @TempDir
    Path dir;

    @Test
    void loadsEveryKey() throws IOException {
        Path file = write(REQUIRED + """
                worker.threads=8
                queue.capacity=250
                retry.max-attempts=5
                request.timeout=2m
                metrics.enabled=true
                """);

        ServiceConfig config = ConfigLoader.load(file);

        assertEquals(URI.create("https://uplink.example.com/v1/events"), config.upstream());
        assertEquals("s3cret", config.apiToken());
        assertEquals(8, config.workerThreads());
        assertEquals(250, config.queueCapacity());
        assertEquals(5, config.retryAttempts());
        assertEquals(Duration.ofMinutes(2), config.requestTimeout());
        assertTrue(config.metricsEnabled());
    }

    @Test
    void optionalKeysUseTheirDefaults() throws IOException {
        ServiceConfig config = ConfigLoader.load(write(REQUIRED));

        assertEquals(ConfigLoader.DEFAULT_WORKER_THREADS, config.workerThreads());
        assertEquals(ConfigLoader.DEFAULT_QUEUE_CAPACITY, config.queueCapacity());
        assertEquals(ConfigLoader.DEFAULT_RETRY_ATTEMPTS, config.retryAttempts());
        assertEquals(ConfigLoader.DEFAULT_REQUEST_TIMEOUT, config.requestTimeout());
        assertFalse(config.metricsEnabled());
    }

    @Test
    void parsesAllTimeoutUnits() throws IOException {
        assertEquals(
                Duration.ofMillis(500),
                ConfigLoader.load(write(REQUIRED + "request.timeout=500ms\n")).requestTimeout());
        assertEquals(
                Duration.ofSeconds(45),
                ConfigLoader.load(write(REQUIRED + "request.timeout=45s\n")).requestTimeout());
    }

    @Test
    void toleratesSurroundingWhitespace() throws IOException {
        ServiceConfig config = ConfigLoader.load(write(REQUIRED + "worker.threads = 8  \nmetrics.enabled=TRUE \n"));

        assertEquals(8, config.workerThreads());
        assertTrue(config.metricsEnabled());
    }

    @Test
    void acceptsAZeroRetryCount() throws IOException {
        assertEquals(0, ConfigLoader.load(write(REQUIRED + "retry.max-attempts=0\n")).retryAttempts());
    }

    @Test
    void apiTokenIsRequired() throws IOException {
        assertRejected("upstream.url=https://uplink.example.com/v1/events\n", "api.token");
    }

    @Test
    void upstreamUrlIsRequired() throws IOException {
        assertRejected("api.token=s3cret\n", "upstream.url");
    }

    @Test
    void rejectsAnUpstreamUrlThatIsNotAnAbsoluteHttpUrl() throws IOException {
        assertRejected("api.token=s3cret\nupstream.url=uplink.example.com\n", "upstream.url");
        assertRejected("api.token=s3cret\nupstream.url=https://exa mple.com\n", "upstream.url");
        assertRejected("api.token=s3cret\nupstream.url=ftp://example.com\n", "upstream.url");
    }

    @Test
    void rejectsAWorkerCountThatIsNotANumber() throws IOException {
        assertRejected(REQUIRED + "worker.threads=4x\n", "worker.threads", "4x");
    }

    @Test
    void rejectsNumbersBelowTheirMinimum() throws IOException {
        assertRejected(REQUIRED + "worker.threads=0\n", "worker.threads", "at least 1");
        assertRejected(REQUIRED + "queue.capacity=0\n", "queue.capacity", "at least 1");
        assertRejected(REQUIRED + "retry.max-attempts=-1\n", "retry.max-attempts", "at least 0");
    }

    @Test
    void rejectsAnEmptyOptionalValue() throws IOException {
        assertRejected(REQUIRED + "queue.capacity=\n", "queue.capacity");
    }

    @Test
    void rejectsATimeoutWithoutAUnit() throws IOException {
        assertRejected(REQUIRED + "request.timeout=30\n", "request.timeout", "30");
    }

    @Test
    void rejectsATimeoutTooLargeToRepresent() throws IOException {
        assertRejected(REQUIRED + "request.timeout=99999999999999999999s\n", "request.timeout");
    }

    @Test
    void rejectsAMetricsFlagThatIsNotTrueOrFalse() throws IOException {
        assertRejected(REQUIRED + "metrics.enabled=yes\n", "metrics.enabled", "yes");
    }

    @Test
    void rejectsAMisspelledKey() throws IOException {
        assertRejected(REQUIRED + "worker.thread=8\n", "worker.thread");
    }

    @Test
    void rejectsAMissingFile() {
        Path missing = dir.resolve("absent.properties");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(missing));

        assertTrue(error.getMessage().contains(missing.toString()), error.getMessage());
    }

    @Test
    void reportsEveryProblemAtOnce() throws IOException {
        Path file = write("upstream.url=https://uplink.example.com\nworker.threads=4x\nmetrics.enabled=yes\n");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertEquals(3, error.problems().size(), error.getMessage());
    }

    private void assertRejected(String content, String... expectedInMessage) throws IOException {
        Path file = write(content);

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        for (String expected : expectedInMessage) {
            assertTrue(error.getMessage().contains(expected), error.getMessage());
        }
    }

    private Path write(String content) throws IOException {
        return Files.writeString(dir.resolve("config.properties"), content);
    }
}

