    private final Properties properties;
    private final List<String> problems = new ArrayList<>();

    private ConfigLoader(Properties properties) {
        this.properties = properties;
    }

    public static ServiceConfig load(Path file) {
        ConfigLoader loader = new ConfigLoader(read(file));
        ServiceConfig config = loader.parse();
        if (!loader.problems.isEmpty()) {
            throw new ConfigException(file.toString(), loader.problems);
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException(file.toString(), List.of("cannot read the file: " + e));
        }
        return properties;
    }

    private ServiceConfig parse() {
        rejectUnknownKeys();
        return new ServiceConfig(
                upstream(),
                required("api.token"),
                intValue("worker.threads", DEFAULT_WORKER_THREADS, 1),
                intValue("queue.capacity", DEFAULT_QUEUE_CAPACITY, 1),
                intValue("retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0),
                duration("request.timeout", DEFAULT_REQUEST_TIMEOUT),
                booleanValue("metrics.enabled", false));
    }

    private void rejectUnknownKeys() {
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add(key + " is not a known key (known keys: " + new TreeSet<>(KNOWN_KEYS) + ")");
            }
        }
    }

    /** The trimmed value, or null when the key is absent. */
    private String value(String key) {
        String raw = properties.getProperty(key);
        return raw == null ? null : raw.trim();
    }

    private String required(String key) {
        String value = value(key);
        if (value == null || value.isEmpty()) {
            problems.add(key + " is required");
            return null;
        }
        return value;
    }

    private URI upstream() {
        String raw = required("upstream.url");
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            if (isHttp(uri)) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        problems.add("upstream.url must be an absolute http or https URL, was \"" + raw + "\"");
        return null;
    }

    private static boolean isHttp(URI uri) {
        String scheme = uri.getScheme();
        return ("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme)) && uri.getHost() != null;
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String raw = value(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw);
            if (value >= minimum) {
                return value;
            }
        } catch (NumberFormatException e) {
            // reported below
        }
        problems.add(key + " must be a whole number, at least " + minimum + ", was \"" + raw + "\"");
        return defaultValue;
    }

    private Duration duration(String key, Duration defaultValue) {
        String raw = value(key);
        if (raw == null) {
            return defaultValue;
        }
        Matcher matcher = DURATION.matcher(raw);
        try {
            if (matcher.matches()) {
                return toDuration(Long.parseLong(matcher.group(1)), matcher.group(2));
            }
        } catch (ArithmeticException | NumberFormatException e) {
            // reported below
        }
        problems.add(key + " must be a whole number followed by ms, s or m (for example 30s), was \"" + raw + "\"");
        return defaultValue;
    }

    private static Duration toDuration(long amount, String unit) {
        return switch (unit) {
            case "ms" -> Duration.ofMillis(amount);
            case "s" -> Duration.ofSeconds(amount);
            default -> Duration.ofMinutes(amount);
        };
    }

    private boolean booleanValue(String key, boolean defaultValue) {
        String raw = value(key);
        if (raw == null) {
            return defaultValue;
        }
        if (raw.equalsIgnoreCase("true") || raw.equalsIgnoreCase("false")) {
            return Boolean.parseBoolean(raw);
        }
        problems.add(key + " must be true or false, was \"" + raw + "\"");
        return defaultValue;
    }
}

