package com.acme.relay;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Starts the relay as a deployer would and checks what they see. */
class MainTest {
    @TempDir
    Path dir;

    @Test
    void refusesToStartOnAnInvalidConfigurationAndSaysWhy() throws Exception {
        Path config = Files.writeString(dir.resolve("config.properties"), """
                upstream.url=https://uplink.example.com/v1/events
                api.token=s3cret
                worker.threads=8x
                """);

        Result result = run(config, "hello\n");

        assertEquals(Main.EXIT_INVALID_CONFIG, result.exitCode());
        assertTrue(result.stderr().contains("worker.threads"), result.stderr());
        assertTrue(result.stderr().contains("8x"), result.stderr());
        assertFalse(result.stderr().contains("\tat "), "no stack trace expected:\n" + result.stderr());
        assertEquals("", result.stdout(), "nothing may be relayed");
    }

    @Test
    void relaysWithAValidConfiguration() throws Exception {
        Path config = Files.writeString(dir.resolve("config.properties"), """
                upstream.url=https://uplink.example.com/v1/events
                api.token=s3cret
                """);

        Result result = run(config, "hello\n");

        assertEquals(0, result.exitCode(), result.stderr());
        assertTrue(result.stdout().contains("hello"), result.stdout());
    }

    private record Result(int exitCode, String stdout, String stderr) {}

    private Result run(Path config, String input) throws IOException, InterruptedException {
        String java = ProcessHandle.current().info().command().orElse("java");
        Path stdout = dir.resolve("stdout.txt");
        Path stderr = dir.resolve("stderr.txt");
        Process process = new ProcessBuilder(
                        java, "-cp", System.getProperty("java.class.path"), Main.class.getName(), config.toString())
                .redirectOutput(stdout.toFile())
                .redirectError(stderr.toFile())
                .start();
        process.getOutputStream().write(input.getBytes(StandardCharsets.UTF_8));
        process.getOutputStream().close();
        int exitCode = process.waitFor();
        return new Result(exitCode, Files.readString(stdout), Files.readString(stderr));
    }
}

